SELECT singer.Name, singer.Age AS youngest_singer_age FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer)
SELECT singer.Name, singer.Age, concert.Year FROM singer INNER JOIN concert ON singer.Singer_ID = concert.Singer_ID WHERE concert.Year = (SELECT MAX(Song_release_year) FROM concert)
SELECT DISTINCT Country FROM singer JOIN stadium ON singer_in_concert.concert_ID = concert.concert_ID AND singer_in_concert.Singer_ID = singer.Singer_ID WHERE Age > 20;
SELECT DISTINCT Country FROM singer WHERE Age > 20
SELECT singer.Country, COUNT(singer.Singer_ID) AS number_of_singers FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT DISTINCT singer.Country, COUNT(singer.Country) AS count_singers_per_nation FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT singer.Name AS Song_Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON singer_in_concert.Concert_ID = concert.Concert_ID WHERE singer.Age > (SELECT AVG(singer.Age) FROM singer)
SELECT singer.Name AS Song_Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID INNER JOIN stadium ON singer_in_concert.stadium_ID = stadium.Stadium_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Location, stadium.Name FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE singer_in_concert.Singer_ID IN (SELECT Singer_ID FROM singer WHERE Age < 100 AND Age > 50)
