SELECT countries.CountryId, countries.CountryName, car_makers.Maker, car_makers.FullName, car_makers.Country FROM countries INNER JOIN car_makers ON countries.CountryId = car_makers.CountryId WHERE car_makers.CountryId IN (SELECT car_makers.CountryId FROM car_makers WHERE car_makers.Maker = 'fiat' OR car_makers.Maker = car_makers.CountryId)
SELECT countries.CountryId, countries.CountryName, car_makers.Maker, car_makers.FullName, car_makers.Country FROM countries JOIN car_makers ON countries.CountryId = car_makers.Country WHERE car_makers.Country = countries.CountryName AND car_makers.Country IN (SELECT countries.CountryId FROM countries WHERE countries.CountryName = 'fiats') ORDER BY countries.CountryId
