SELECT Name FROM employee ORDER BY Age ASC;
SELECT employee.Name, employee.Age, employee.City, employee.Manager_name FROM employee JOIN hiring ON employee.Employee_ID = hiring.Employee_ID JOIN shop ON hiring.Shop_ID = shop.Shop_ID ORDER BY employee.Age DESC;
SELECT City, COUNT(*) AS count FROM employee JOIN hiring ON hiring.Employee_ID = employee.Employee_ID GROUP BY City HAVING COUNT(*) > 1 AND Age < 30;
SELECT employee.City FROM employee JOIN hiring ON hiring.Shop_ID = shop.Shop_ID WHERE employee.Age < 30 AND employee.Age > 0 AND hiring.Is_full_time = 1;
SELECT COUNT(*) AS count, City AS city FROM employee JOIN shop ON employee.City = shop.Location GROUP BY City;
SELECT COUNT(DISTINCT e.City) AS City_count, e.Name AS Name, e.Age AS Age, e.Manager_name AS Manager_name FROM employee e JOIN shop s ON e.City = s.Location GROUP BY e.City;
SELECT e.Name, s.District FROM employee e JOIN shop s ON e.Manager_name = s.Manager_name WHERE s.Number_products = (SELECT MAX(Number_products) FROM shop)
SELECT e.Name, s.District FROM employee e JOIN shop s ON e.Manager_name = s.Manager_name;
SELECT e.Name, s.Location, s.District, e.Name AS Name, s.Number_products, s.Manager_name FROM employee e JOIN shop s ON e.Employee_ID = s.Manager_name ORDER BY s.Number_products DESC;
SELECT employee.Name, shop.Location, shop.District FROM employee INNER JOIN shop ON employee.Employee_ID = shop.Manager_name ORDER BY shop.Number_products DESC;
SELECT e.Name AS Store, e.Age AS Age, e.City AS City FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN shop s ON h.Shop_ID = s.Shop_ID WHERE s.Number_products > (SELECT AVG(e.Number_products) FROM employee e)
SELECT Name FROM shop WHERE Number_products > (SELECT AVG(Number_products) FROM shop)
SELECT e.Name, e.Age, e.City, e.Manager_name, e.Employee_ID, e.Employee_ID AS Employee_ID FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID JOIN evaluation e2 ON e.Employee_ID = e2.Employee_ID ORDER BY e2.Bonus DESC;
SELECT Name FROM employee WHERE Bonus = (SELECT MAX(Bonus) FROM evaluation)
SELECT shop.Name, COUNT(evaluation.Employee_ID) AS total_employees FROM shop JOIN hiring ON shop.Shop_ID = hiring.Shop_ID JOIN employee ON hiring.Employee_ID = employee.Employee_ID JOIN evaluation ON employee.Employee_ID = evaluation.Employee_ID GROUP BY shop.Shop_ID ORDER BY total_employees DESC LIMIT 1;
SELECT shop.Name FROM shop JOIN employee ON shop.Shop_ID = employee.Shop_ID ORDER BY employee.Age DESC LIMIT 1;
SELECT e.Name AS Shop_name FROM employee e JOIN hiring h ON e.Employee_ID = h.Employee_ID WHERE h.Is_full_time = FALSE;
SELECT Name FROM shop WHERE Manager_name IS NULL
SELECT District FROM shop WHERE Number_products < 3000 AND Manager_name IS NOT NULL;
SELECT DISTINCT District FROM shop WHERE Number_products < 3000 AND Number_products > 10000;
