SELECT COUNT(DISTINCT visitor.ID) FROM visitor WHERE visitor.Age < 30
SELECT v.Name FROM visitor v JOIN visit v_visit ON v.ID = v_visit.visitor_ID WHERE v_visit.Level_of_membership > 4 ORDER BY v_visit.Level_of_membership DESC;
SELECT AVG(visitor.Age) FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID WHERE visit.Museum_ID = museum.Museum_ID AND visitor.Level_of_membership <= 4
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS total_visitors FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID GROUP BY museum.Museum_ID ORDER BY total_visitors DESC;
SELECT AVG(museum.Num_of_Staff) FROM museum WHERE Open_Year < '2009'
SELECT museum.Open_Year, visitor.Staff_Number FROM museum INNER JOIN visitor ON museum.Museum_ID = visitor.Museum_ID;
SELECT Name FROM museum WHERE Num_of_Staff > (SELECT MIN(Num_of_Staff) FROM visit WHERE Open_Year > '2010')
SELECT v.ID, v.Name, v.Age FROM visitor v JOIN visit v2 ON v.ID = v2.visitor_ID JOIN museum m ON v2.Museum_ID = m.Museum_ID WHERE v2.Num_of_Ticket > 0;
SELECT id, name, membership_level FROM visitor INNER JOIN visit ON visit.visitor_ID = visitor.ID INNER JOIN museum ON visit.Museum_ID = museum.Museum_ID WHERE visit.Total_spent ORDER BY visit.Total_spent DESC LIMIT 1;
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS visit_count FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID JOIN visitor ON visit.visitor_ID = visitor.ID GROUP BY museum.Museum_ID, museum.Name;
SELECT museum.Name FROM museum JOIN visit ON museum.Museum_ID = visit.Museum_ID WHERE visit.visitor_ID IS NULL;
SELECT visitor.Name, visitor.Age FROM visitor JOIN visit ON visit.visitor_ID = visitor.ID JOIN museum ON visit.Museum_ID = museum.Museum_ID GROUP BY visitor.Name, visitor.Age ORDER BY visitor.Age DESC;
SELECT SUM(visit.Total_spent) AS total_ticket_expense FROM visit JOIN museum ON visit.Museum_ID = museum.Museum_ID JOIN visitor ON visit.visitor_ID = visitor.ID WHERE visitor.Level_of_membership = 'lv 1'
