SELECT players.first_name, players.rankings.ranking FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking IS NULL OR rankings.ranking < (SELECT MIN(ranking) FROM rankings) ORDER BY rankings.ranking ASC LIMIT 3;
