SELECT s.last_name, s.current_address_id, s.permanent_address_id, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s INNER JOIN Addresses ON s.current_address_id = Addresses.address_id INNER JOIN Addresses ON s.permanent_address_id = Addresses.address_id WHERE s.state_province_county = 'North Carolina' AND s.date_left IS NULL;
SELECT s.last_name, s.student_id FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Addresses b ON s.permanent_address_id = b.address_id WHERE a.state_province_county = 'North Carolina' AND s.date_left IS NULL;
