SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s JOIN Semester_Courses sc ON s.student_id = sc.student_id JOIN Courses c ON sc.course_id = c.course_id JOIN Degree_Programs dp ON dp.department_id = c.department_id JOIN Departments d ON dp.department_id = d.department_id WHERE s.date_first_registered < s.date_left ORDER BY s.date_first_registered ASC;
SELECT first_name, middle_name, last_name FROM Students ORDER BY date_first_registered LIMIT 1;
SELECT s.id, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON s.section_id = ssec.section_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON ssec.department_id = dp.department_id JOIN Transcripts t ON ssec.transcript_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Courses c2 ON tc.student_course_id = c2.course_id JOIN Student_Enrolment_Courses sc2 ON sc2.student_course_id = sc.course_id;
SELECT S.id, S.line_1, S.line_2 FROM Addresses S JOIN Students S ON S.address_id = S.current_address_id ORDER BY S.line_1, S.line_2 DESC LIMIT 1;
SELECT DISTINCT Semester.semester_name AS semester, Degree_Programs.degree_program_id AS degree_program_id FROM Semesters INNER JOIN Degree_Programs ON Semesters.semester_id = Degree_Programs.semester_id;
SELECT DISTINCT S.semester_id FROM Semesters S JOIN Students S2 ON S.semester_id = S2.date_left JOIN Addresses A ON S2.current_address_id = A.address_id JOIN Departments D ON S2.department_id = D.department_id JOIN Degree_Programs DP ON S2.department_id = DP.department_id JOIN Student_Enrolment_Courses SC ON S2.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S2C ON S2C.section_id = S2.section_id JOIN Transcripts T ON S2C.transcript_id = T.transcript_id JOIN Transcript_Contents TC ON TC.student_course_id = S2C.student_course_id;
