SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals INNER JOIN Dogs ON Dogs.owner_id = Professionals.owner_id INNER JOIN Owners ON Owners.owner_id = Professionals.owner_id INNER JOIN Treatments ON Treatments.professional_id = Professionals.professional_id INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code WHERE Professionals.state = 'Indiana' OR Treatments.date_of_treatment > 2;
SELECT Dogs.name FROM Dogs INNER JOIN Treatments ON Dogs.dog_id = Treatments.dog_id INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id INNER JOIN Professionals ON Treatments.professional_id = Professionals.professional_id WHERE Treatments.cost_of_treatment > 1000;
