SELECT Dogs.id, Dogs.zip_code FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Sizes ON Dogs.size_code = Sizes.size_code JOIN Breeds ON Dogs.breed_code = Breeds.breed_code GROUP BY Dogs.id, Dogs.zip_code ORDER BY SUM(Dogs.weight) DESC LIMIT 1;
SELECT o.first_name, o.last_name FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id JOIN Dogs d ON d.owner_id = o.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t2 ON t.treatment_type_code = t2.treatment_type_code WHERE t.cost_of_treatment < t2.cost_of_treatment;
SELECT o.first_name, o.last_name FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE d.size_code IN (SELECT size_code FROM Sizes WHERE size_description = 'less expansive' AND d.breed_code IN (SELECT breed_code FROM Breeds WHERE breed_name = 'dog') AND p.role_code = 'treatment') AND p.first_name = 'theor' AND p.last_name = 'first_name'
